INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_hyperscaler', 'hyperscaler', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_hyperscaler_0', 'e_hyperscaler', 0, 'hyperscaler', '[]', 'One of the few companies that run cloud computing and storage on a huge scale.', 'Use it only for the few giant cloud companies, never for your own platform or a growing vendor. With people who do not know the term, say what it means for them, such as cost.', 'We are not going to beat a hyperscaler on inference cost, so the case has to rest on the data staying ours.', '[{"text":"A steering committee asks why the firm cannot simply build the same capacity in-house, and you need the collective noun for the three vendors that already have it.","setting":"work"},{"text":"An MD wants to know why frontier model training happens at only a few companies in the world, and the answer is who owns the hardware.","setting":"work"},{"text":"Procurement asks which suppliers count as strategic infrastructure rather than ordinary software vendors, and you want the term for that tier.","setting":"work"},{"text":"Writing an architecture note, you need one word for AWS, Azure and Google Cloud as a class so you stop listing all three every time.","setting":"work"}]', '["A data centre a company builds and runs purely for its own internal systems.","A vendor that resells another company''s cloud capacity under its own brand.","The unit of computing you rent by the hour and give back when the job is finished.","A pricing model where you pay only for the computing you actually consume, billed by the second.","A company that keeps its servers in its own building rather than renting them from anyone."]', '["semantic layer","persist","gravitas","bolster","despondent"]', 'a giant cloud provider', '["a small software startup","a phone maker","a website design agency"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
