INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_gravitas', 'gravitas', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_gravitas_0', 'e_gravitas', 0, 'gravitas', '[]', 'A serious, calm way of behaving that makes other people respect you and listen.', 'Never say it about yourself, and save it for serious situations. As feedback it is vague, so name one specific thing the person can do differently.', 'He took the audit question with real gravitas, which is why the board stopped pushing on it.', '[{"text":"A new director takes a hostile question from the board without flinching, and you want the word for what made the room settle.","setting":"work"},{"text":"You are telling a colleague why a senior audience did not take her recommendation seriously, and it was not the content.","setting":"work"},{"text":"A sponsor asks what is missing from the candidate who is technically the strongest on the shortlist.","setting":"work"},{"text":"A friend describes a wedding speech given by someone whose bearing made the whole room go quiet.","setting":"life"},{"text":"Watching an actor play a judge, you want the word for the weight he carries that the younger cast do not.","setting":"life"}]', '["The habit of speaking far longer than the point needs.","The nerves that show when someone is asked a question they were not expecting.","A reputation for being right, built up over years of small correct calls.","The formal authority a role carries, written down in a job description and an org chart.","A speaking style that fills a room with energy and gets people excited about a plan."]', '["advocate for","primitive","broad","by and large","lean on"]', 'a serious, respected manner', '["a loud, pushy manner","a habit of speaking too long","a talent for small talk"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
