INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_executive_presence_finesse', 'executive presence/finesse', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_executive_presence_finesse_0', 'e_executive_presence_finesse', 0, 'executive presence', '[]', 'Coming across as calm, clear and senior enough to be handed a decision.', 'Only say it about other people. As feedback it is vague, so add a specific behaviour, such as leading with your recommendation.', 'Her content is watertight; what we are coaching is executive presence, starting with not burying the ask on slide nine.', '[{"text":"A brilliant engineer keeps losing the room in front of the investment committee, and you need the name for the thing he is missing.","setting":"work"},{"text":"Your manager asks what separates two candidates for a director role whose track records are identical.","setting":"work"},{"text":"You are designing a coaching plan for someone who knows more than anyone in the room but is never the one the MD turns to.","setting":"work"},{"text":"A friend preparing for a panel interview asks what the panel is really judging in the first two minutes.","setting":"life"}]', '["A record of delivering what you promised, quarter after quarter.","The number of people who report to you, directly and indirectly.","The ability to speak a second language well enough to negotiate in it.","The set of decisions a leader is formally allowed to make without asking.","The rank a job sits at in a company''s grading system, published for everyone to see."]', '["persist","fan-out","daily driver","wordsmith","lay of the land"]', 'a calm, confident leader''s style', '["a formal job title","a habit of avoiding hard decisions","a strong technical skill set"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
