INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_executive_presence_finesse_0_production', 's_executive_presence_finesse_0', 'production', NULL, NULL, 11, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_executive_presence_finesse_1', 'e_executive_presence_finesse', 1, 'finesse', '[]', 'Skill in handling something delicate so smoothly that the difficulty never shows.', 'As a verb it can suggest you hid a problem instead of solving it. Do not use it about numbers or facts, especially with auditors or in writing.', 'He finessed the headcount question without promising anything, and the MD moved on.', '[{"text":"A colleague deflects a budget question without either lying or conceding ground, and you want the word for how deftly it was done.","setting":"work"},{"text":"You are describing how a tense vendor negotiation was closed with nobody losing face.","setting":"work"},{"text":"A friend steered her parents off a touchy subject at dinner with no argument at all.","setting":"life"},{"text":"A footballer beats a defender with one soft touch instead of pace, and you want the word for that kind of skill.","setting":"life"}]', '["Brute force applied until an obstacle gives way.","Doing a job to a standard nobody asked for, at a cost nobody agreed to.","A rehearsed answer prepared in advance for a question you expect to be asked.","The willingness to say the uncomfortable thing in a room that does not want to hear it.","The care taken to record exactly how a decision was reached, so it can be audited later."]', '["nontrivial","squarely","first order effects","in pockets","deliberate"]', 'a skill with delicate situations', '["a lack of care","a strict set of rules","a willingness to take large risks"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_executive_presence_finesse_1_recognition', 's_executive_presence_finesse_1', 'recognition', NULL, NULL, 12, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
