INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_buy_in', 'buy-in', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_buy_in_0', 'e_buy_in', 0, 'buy-in', '["buy in"]', 'Genuine agreement from the people whose help you need, not just their signature.', 'Only claim it when people truly agree, because a signature alone does not count. Saying you need to get it from your own team can sound like you plan to push them.', 'We have the funding, what we do not have is buy-in from the two teams who would have to change how they release.', '[{"text":"The steering committee has approved your programme, but the two delivery leads whose work it changes still think it is a mistake.","setting":"work"},{"text":"You are explaining to a sponsor why a technically finished rollout has stalled: the people whose process it changes were never really with you.","setting":"work"},{"text":"Writing a plan, you need a word for the thing a signature on its own does not give you.","setting":"work"},{"text":"Your family agrees in principle to the mountain holiday, but half of them are plainly humouring you.","setting":"life"},{"text":"A neighbour wants the shared driveway resurfaced and asks what she needs from the other households before anyone spends a penny.","setting":"life"}]', '["A formal signature recorded so that a project may begin.","The money a partner puts in to take a share of a business.","The share of a market a product has taken from its competitors.","Written permission from a committee that has reviewed both the risks and the cost.","The quiet compliance of a team that has stopped arguing but has not changed its mind."]', '["despondent","first principles","center of excellence","idempotent","blanket approval"]', 'an agreement to back a plan', '["a delay to a project","a strong objection to a plan","a list of project costs"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
