INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_sponsorship', 'sponsorship', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_sponsorship_0', 'e_sponsorship', 0, 'sponsorship', '["sponsor"]', 'A senior person using their own reputation and influence to support a person or project.', 'A sponsor speaks up for you, while a mentor only gives advice, so do not call an adviser your sponsor. It can also mean paid advertising, so say executive sponsor first.', 'The programme has funding and it has sponsorship, so when finance pushed back last week it was not my fight alone.', '[{"text":"A director asks what the failed initiative was really missing, and the honest answer is that nobody senior owned it once it got hard.","setting":"work"},{"text":"You are advising a colleague who has no shortage of mentors and keeps being passed over, and you want the word for the thing mentoring is not.","setting":"work"},{"text":"Before starting a programme that cuts across three teams, you want one word for the senior commitment you will ask for beyond the budget.","setting":"work"},{"text":"A friend''s daughter is trying to break into an industry where advice is easy to come by and an opened door is not.","setting":"life"},{"text":"At a climbing club an experienced member vouches for a newcomer and puts her own standing behind them.","setting":"life"}]', '["Advice given privately to someone earlier in their career.","The budget line that pays for a programme''s staff and tools.","A written record of who is accountable for each deliverable in a plan.","The practice of pairing a new joiner with a colleague who answers their questions for a month.","A senior person''s public disagreement with a decision that their own leadership has taken."]', '["obfuscate","attuned","build that muscle","diaspora","rectify"]', 'a senior person''s active backing', '["a formal job review","a transfer to a new team","a written complaint about a manager"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
