INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_cognizant', 'cognizant', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_cognizant_0', 'e_cognizant', 0, 'cognizant', '["cognisant"]', 'Aware of something and visibly taking it into account when a decision is made.', 'Use it in writing, where it records that you knew about a risk. Out loud it sounds stiff, so say aware, and note that it is also the name of an IT company.', 'We are cognizant of the concentration risk, and the phased rollout is the answer to it.', '[{"text":"You are drafting a paper and want a formal way to record that the team already weighed the risk the committee is about to raise.","setting":"work"},{"text":"A regulator asks whether the implications were understood at the time, and they were.","setting":"work"},{"text":"Writing to a landlord about a repair, you want to acknowledge that he has other tenants without sounding casual about your own problem.","setting":"life"},{"text":"Explaining a decision to a family member, you want a slightly formal way of saying their situation was in view the whole way through.","setting":"life"}]', '["Told about something after the decision has already been made.","Able to explain a subject clearly to someone who has never met it.","Responsible for a piece of work and answerable for how it turns out.","Kept informed of progress at regular intervals without being asked to approve anything.","Trained in a procedure well enough to carry it out without checking the manual first."]', '["eschew","broad","north star","daily driver","flywheel effect"]', 'fully aware of something', '["angry about something","unwilling to take any action","proud of something"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
