INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_obfuscate', 'obfuscate', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_obfuscate_0', 'e_obfuscate', 0, 'obfuscate', '["obfuscation"]', 'To make something hard to understand on purpose.', 'It accuses someone of trying to mislead. For a colleague''s work that is simply unclear, say unclear or obscure instead.', 'Their per-token pricing obfuscates the real cost, so I have rebuilt it as one number per thousand queries.', '[{"text":"A vendor''s pricing page looks designed so that you cannot work out what you would actually pay, and you want the word that says the confusion is the point.","setting":"work"},{"text":"In a review you want to name what a paper is doing when it buries a bad number under three layers of terminology.","setting":"work"},{"text":"You are arguing that adding yet more caveats to the report would hide the finding rather than qualify it.","setting":"work"},{"text":"A friend''s phone contract seems written so the exit fee is impossible to find, and you want the accusing word for it.","setting":"life"},{"text":"Talking about an interview where a politician used a great many words to avoid a plain yes or no.","setting":"life"}]', '["To check a claim against its source.","To repeat a point until it lands.","To explain something clearly enough for a beginner.","To shorten a document without losing its meaning.","To translate a technical answer into business terms."]', '["frontier","dogfooding","hot-swap","institutional knowledge","semantic layer"]', 'to confuse on purpose', '["to delay a decision","to complain in public","to agree without thinking"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
