INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_trivial_nontrivial', 'trivial/nontrivial', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_trivial_nontrivial_0', 'e_trivial_nontrivial', 0, 'trivial', '[]', 'So small or easy that it is not worth spending time on.', 'About other people''s work it sounds dismissive. Even about your own work be careful, because people remember when a trivial change breaks something.', 'The schema change is trivial; the migration for the three teams downstream is not.', '[{"text":"Your tech lead asks how big the config change is, and the honest answer is that reviewing it will take longer than making it.","setting":"work"},{"text":"You are separating the half of the migration that takes an afternoon from the half that takes a month, and you need the dismissive adjective for the easy half.","setting":"work"},{"text":"A friend is agonising over two phone plans that differ by a pound a month, and you want a word for the size of that difference.","setting":"life"},{"text":"Someone apologises at length for a favour that cost you nothing, and you want one adjective to wave it away.","setting":"life"}]', '["Deferred to a later release on purpose.","Cheap to build and expensive to run.","Left undone because nobody ever owned it.","Small in size but serious in what it sets off downstream.","Difficult to explain but easy to do once you have seen it."]', '["sponsorship","finesse","substantial","pick your brain","buy-in"]', 'very small or easy', '["harder than it looks","costly and slow","strange and hard to explain"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_trivial_nontrivial_0_recognition', 's_trivial_nontrivial_0', 'recognition', NULL, NULL, 40, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
