INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_trivial_nontrivial_0_production', 's_trivial_nontrivial_0', 'production', NULL, NULL, 43, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_trivial_nontrivial_1', 'e_trivial_nontrivial', 1, 'nontrivial', '["non-trivial"]', 'Not simple, and harder or larger than the person asking has assumed.', 'It suits technical readers. With senior leaders give a number right after it, and use it only when you have actually estimated the work.', 'Rewiring auth for the new tenant model is nontrivial, so call it three sprints rather than a fortnight.', '[{"text":"An MD asks whether adding a second language to the assistant is just a config change, and it is a month of work.","setting":"work"},{"text":"You want to warn a project manager that a change she assumes is small reaches into three services, using understatement rather than alarm.","setting":"work"},{"text":"A friend asks whether getting the sofa up two flights of stairs is a job for two people, and it is a great deal more work than she thinks.","setting":"life"},{"text":"You are telling someone that learning to drive a manual car is harder than they are assuming, without putting them off it.","setting":"life"}]', '["Simple to describe and simple to build.","Impossible with the tools currently available at any price.","Expensive in money but cheap in the time it takes to finish.","Well understood by the team that owns it and by nobody else in the building.","Held up by a dependency on another team rather than by the work itself."]', '["verbose","inroads","watch outs","blanket approval","serialize"]', 'harder than it looks', '["very small or easy","known to very few people","cheap and quick"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
