INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_substantiate_substantial', 'substantiate/substantial', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_substantiate_substantial_0', 'e_substantiate_substantial', 0, 'substantiate', '["substantiated"]', 'To back a claim with evidence that someone else can check.', 'Asking someone to substantiate a claim shows you doubt it. For a colleague''s claim in front of their boss, just ask for the source instead.', 'I can substantiate the thirty per cent figure from two quarters of tickets, it is not a vendor number.', '[{"text":"A director accepts your recommendation and then asks where the number came from, and you want the verb for supplying that.","setting":"work"},{"text":"You are reviewing a paper whose central claim rests on one unsourced statistic, and you want to name politely what it is missing.","setting":"work"},{"text":"A friend repeats a health claim they read online, and you want the word for what you would want before believing it.","setting":"life"},{"text":"An insurer asks you to back the value of a lost item with something more than your word for it.","setting":"life"}]', '["To repeat a claim until people accept it.","To state something plainly and without hedging.","To write down what was decided so it can be found later.","To argue a case on behalf of somebody who is not in the room.","To take an existing figure and adjust it for inflation over time."]', '["persistence","panopticon","play it by ear","tectonic shift","disambiguate"]', 'to prove with evidence', '["to guess without facts","to delay a decision","to repeat word for word"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_0_recognition', 's_substantiate_substantial_0', 'recognition', NULL, NULL, 48, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_0_identify', 's_substantiate_substantial_0', 'identify', NULL, NULL, 49, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_0_reverse', 's_substantiate_substantial_0', 'reverse', NULL, NULL, 50, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_0_production', 's_substantiate_substantial_0', 'production', NULL, NULL, 51, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_substantiate_substantial_1', 'e_substantiate_substantial', 1, 'substantial', '[]', 'Large enough to matter, said of an amount or a change without giving a number.', 'People will ask how much, so give the number if you have it. Use the word alone only when you are not allowed to share the figure.', 'There is a substantial gap between what the pilot proved and what the rollout is assuming.', '[{"text":"You want to call the cost reduction meaningful in a paper where you are not allowed to publish the exact figure.","setting":"work"},{"text":"A colleague''s contribution to the project went far beyond a review, and you want to credit it in writing.","setting":"work"},{"text":"Describing a restaurant to a friend, you want a word for portions that genuinely fill you rather than decorate the plate.","setting":"life"},{"text":"A neighbour asks what the roof repair cost, and you want to convey that it was a lot without naming the figure.","setting":"life"}]', '["Small enough to ignore for now.","Measured precisely and reported to two decimal places.","Growing steadily but from a very small starting point.","Set aside in a budget for costs that have not yet been identified in any detail.","Counted twice by mistake because two systems both reported the same transaction."]', '["bolster","long-horizon","finesse","north star","substrate"]', 'large enough to matter', '["happening every day","hard to understand","known only to a few people"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_1_recognition', 's_substantiate_substantial_1', 'recognition', NULL, NULL, 52, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
