INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_delibrate_intentional', 'delibrate/intentional', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_delibrate_intentional_0', 'e_delibrate_intentional', 0, 'deliberate', '["intentional","deliberately","intentionally"]', 'Done on purpose and with thought, rather than by accident.', 'About someone else''s action it says they chose to do it, which is an accusation. About your own plan it can sound like an excuse for being slow, so say on purpose.', 'The gap in the rollout schedule is deliberate, we want a full month of production data before the next region goes live.', '[{"text":"A sponsor reads the gap in your roadmap as a slip, and you need to say the pause was chosen rather than accidental.","setting":"work"},{"text":"In an incident review you have to state whether the configuration change was made knowingly, and it was.","setting":"work"},{"text":"You are describing a hiring approach that moves slowly by design, because each early hire shapes the team.","setting":"work"},{"text":"A friend asks whether you left a name off the invitation by mistake, and you did not.","setting":"life"},{"text":"Someone speaks in an unhurried way with every word chosen, and you want the adjective for that manner.","setting":"life"}]', '["Done quickly, before anyone has time to object.","Agreed by everyone in the room without a vote.","Left to whoever picks it up first, with no owner named anywhere.","Repeated so often that it has become a habit nobody questions any more.","Chosen because it was the only option anybody could think of at the time."]', '["panopticon","contrived","idempotent","unequivocal","enmeshed"]', 'done on purpose', '["done very quickly","done in secret","done without any help"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
