INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_daily_driver', 'daily driver', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_daily_driver_0', 'e_daily_driver', 0, 'daily driver', '[]', 'The tool you actually use every day, rather than a backup or one you are still testing.', 'Only say it about a tool you really use, because people will ask what its problems are. It is casual, so avoid it in formal written recommendations.', 'Claude is my daily driver, I keep the others around for the one or two jobs they are better at.', '[{"text":"A colleague asks which of the three coding assistants you actually reach for, not which ones you have tried.","setting":"work"},{"text":"In a tooling review you want to separate the editor most engineers live in from the ones installed once and forgotten.","setting":"work"},{"text":"A friend with three bicycles is asked which one he rides to work and which he keeps for weekends.","setting":"life"},{"text":"You keep a good camera for holidays and photograph everything else on your phone, and you want the term for the phone.","setting":"life"}]', '["A tool bought and never installed.","A spare kept in a drawer in case the main one fails.","The version of a product given to reviewers before release.","The tool a company has standardised on and pays for, whether or not anyone enjoys using it.","A product used only for demonstrations, set up carefully so nothing goes wrong on stage."]', '["inroads","hot-swap","in pockets","asymmetric","center of excellence"]', 'the tool you use every day', '["a tool you are still testing","a backup you rarely use","the person who leads a team"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
