INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_incremental', 'incremental', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_incremental_0', 'e_incremental', 0, 'incremental', '["incrementally"]', 'Proceeding by small additions, each one adding a little to what is already there.', 'About how work is delivered it is praise, but about results it means the gains are small. In finance it means the extra amount above the usual baseline.', 'The gains are incremental per release, and it is the compounding across two quarters that the case actually rests on.', '[{"text":"A committee asks how you will de-risk an eighteen-month programme, and your answer is small releases that each stand on their own.","setting":"work"},{"text":"You are describing model improvements that are real but modest, and you want the honest word for them before somebody else uses it against you.","setting":"work"},{"text":"You are explaining how you are learning a language: twenty minutes a night, nothing dramatic.","setting":"life"},{"text":"A friend asks whether the new phone is worth the upgrade, and every improvement in it is a small one.","setting":"life"}]', '["Done all at once, with no way back.","Replaced entirely rather than repaired.","Growing by a fixed percentage each period rather than a fixed amount.","A change that removes a feature instead of adding one, to keep the product simple.","Work that cannot be split up, because none of it is any use until all of it is done."]', '["sponsorship","squarely","amenable","exacerbate","first order effects"]', 'happening in small steps', '["happening all at once","getting smaller over time","happening by chance"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
