INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_progressive', 'progressive', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_progressive_0', 'e_progressive', 0, 'progressive', '["progressively"]', 'Advancing in stages, each stage going further than the last.', 'About people, policy or values it is heard as political, so say phased or staged there. In tax and pricing it means rates that rise as the amount rises.', 'We will do a progressive rollout, one desk this week, the floor next week, and the region only after two clean weeks.', '[{"text":"You are proposing to widen a release from one desk to a floor to the whole region, one step at a time, and want the adjective for that shape of rollout.","setting":"work"},{"text":"A designer asks what to call an interface that shows the simple case first and reveals the advanced controls only when they are asked for.","setting":"work"},{"text":"In a risk paper you need a word for exposure that grows in planned stages rather than arriving all at once.","setting":"work"},{"text":"Your optician is describing lenses whose strength changes gradually from the top of the lens to the bottom.","setting":"life"},{"text":"A friend''s training plan adds a little more distance every week, and you want the adjective for that kind of build-up.","setting":"life"}]', '["Released to everyone at the same moment.","Repeated identically each time it runs.","Held back until every part of it is finished and signed off.","Rolled back to the previous version the moment anything looks wrong.","Reversed one step at a time until the system is back where it started."]', '["second order effects","ducks in a row","advocate","unequivocal","community of practice"]', 'happening in stages', '["happening all at once","done by hand","getting weaker over time"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_progressive_0_recognition', 's_progressive_0', 'recognition', NULL, NULL, 68, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
