INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_ducks_in_a_row', 'ducks in a row', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_ducks_in_a_row_0', 'e_ducks_in_a_row', 0, 'ducks in a row', '["get your ducks in a row","ducks lined up"]', 'All the preparation done in advance, so nothing is missing when the moment comes.', 'It is informal and friendly between peers, but telling someone senior to get theirs in a row says they are disorganised. In writing, name the actual preparation.', 'Before this goes to the committee let us get our ducks in a row on the cost model and the security sign-off.', '[{"text":"Two weeks before a board paper you want to tell your team informally that every approval, number and sign-off has to be settled first.","setting":"work"},{"text":"A peer is about to ask for headcount with no business case and no hiring plan ready behind it.","setting":"work"},{"text":"A friend is buying a flat and has not yet sorted the mortgage, the survey or the solicitor.","setting":"life"},{"text":"Before a family trip abroad you want a phrase for getting the passports, the insurance and the bookings all settled in advance.","setting":"life"}]', '["A list of everything that could go wrong, each with an owner.","Deciding as you go, taking your lead from how things actually develop.","The order in which tasks must run, drawn as a chain of dependencies.","A meeting held after the event to work out what went wrong and who should fix it.","The single person whose approval is needed before anything else is allowed to move."]', '["buy-in","ephemeral","executive presence","semantic layer","diaspora"]', 'fully prepared in advance', '["running late","working on too many things","in total agreement"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
