INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_lean_on', 'lean on', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_lean_on_0', 'e_lean_on', 0, 'lean on', '["leaned on","leaning on"]', 'To rely on someone or something to do part of the work for you.', 'It can also mean to put pressure on someone, so be clear which you mean. When you say it about a colleague, say exactly how they helped.', 'For the regulatory wording we leaned on Legal rather than inventing our own language.', '[{"text":"You are explaining how the team delivered a compliance section without hiring an expert: somebody else''s knowledge carried it.","setting":"work"},{"text":"In a design discussion you want to say the new service should use the identity system that already exists rather than reinvent it.","setting":"work"},{"text":"A director asks how you will cover the gap while the role is unfilled, and the answer is a colleague''s goodwill and time.","setting":"work"},{"text":"A friend is going through a hard month and you want to tell them to draw on the people around them.","setting":"life"},{"text":"You are describing how you got through a house move on your brother''s van and two very patient friends.","setting":"life"}]', '["To ask someone to explain their reasoning before you decide.","To take a job over from the person who was doing it.","To hand a decision upwards so that somebody more senior owns it.","To spread one piece of work across many workers running at the same time.","To deliberately do without something you could easily have had, as a matter of principle."]', '["first principles","primitive","eschew","sleuthing","substantiate"]', 'to rely on for help', '["to argue with","to report to a manager","to take credit for"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
