INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_lay_of_the_land', 'lay of the land', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_lay_of_the_land_0', 'e_lay_of_the_land', 0, 'lay of the land', '["lie of the land","the lay of the land"]', 'How things really work somewhere new, who decides and what has already been tried.', 'It is fine in your first month but sounds like stalling later. Do not use it in an update where people are waiting for a decision or asking about results.', 'Give me two weeks with the delivery leads to get the lay of the land before I propose any changes.', '[{"text":"You have joined a new organisation and want to describe the first month as working out who decides what before you propose anything.","setting":"work"},{"text":"Before a customer workshop you ask a colleague to brief you on the politics and the history you will be walking into.","setting":"work"},{"text":"You have moved to a new neighbourhood and spend a fortnight finding which shops, which routes and which neighbours matter.","setting":"life"},{"text":"A friend starting at a new school asks how long it takes before things stop feeling foreign.","setting":"life"}]', '["The published organisation chart, showing who reports to whom.","A map of which systems talk to which, drawn before any change is made.","A list of every system a team owns, kept up to date for audit purposes.","A survey of what competitors are selling and at what price, refreshed every quarter.","The full list of everything a team has agreed to deliver this quarter, ranked in order."]', '["lend itself","disambiguate","modality","vertical","trivial"]', 'how a new workplace works', '["how to get promoted quickly","a promotion to a senior job","a plan for the next year"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
