INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_bolster', 'bolster', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_bolster_0', 'e_bolster', 0, 'bolster', '["bolstered","bolstering"]', 'To strengthen something that is already there but is not strong enough on its own.', 'It admits the thing is weak now, so use it only when you mean that. Use it for things such as an argument, savings, or confidence, and not for machines or deadlines.', 'The numbers are directionally right, but one more independent source would bolster them before this goes to the board.', '[{"text":"Your recommendation rests entirely on a single vendor''s figures, and you are proposing a second, independent source so it survives scrutiny.","setting":"work"},{"text":"In a review a junior colleague makes a correct point that lands weakly, and you want to put your own evidence behind it without taking the point over.","setting":"work"},{"text":"A friend''s visa application is complete but unconvincing on its own, and you are suggesting a letter from their employer go in alongside it.","setting":"life"},{"text":"Your savings would just about cover six months without work, and your partner asks what you plan to do about the margin before you resign.","setting":"life"},{"text":"A nervous friend ran their speech past three people the night before, and you are describing what that did for them.","setting":"life"}]', '["To avoid something deliberately and on principle, having had the option to take it.","To make a bad situation worse than it already was.","To rely on someone else to carry part of the weight of the work.","To replace a running part of a system without stopping the system around it.","To put right something that was wrong, such as an error, an imbalance, or a debt you owe."]', '["obscure","lend itself","wordsmith","scaffolding","idempotent"]', 'to strengthen', '["to delay","to explain in detail","to hide on purpose"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
