INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_verbose', 'verbose', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_verbose_0', 'e_verbose', 0, 'verbose', '["verbosity"]', 'Using far more words than the point needs.', 'It criticises the writer and sounds rude about someone''s answer in front of others. In engineering, verbose logs simply means detailed logs, so say which meaning you intend.', 'It is accurate, but it is verbose. The committee will read the opening paragraph and stop.', '[{"text":"A colleague''s weekly update runs to four paragraphs where two lines would do, and you are giving them the feedback privately.","setting":"work"},{"text":"You reread your own memo before sending it and notice it takes half a page to reach the ask.","setting":"work"},{"text":"A friend forwards you the terms of a phone contract that says almost nothing across two thousand words.","setting":"life"},{"text":"You gave up on a novel a hundred pages in because every scene took three pages to move an inch.","setting":"life"}]', '["So little known that most people would not follow it.","Deliberately hard to understand.","Big enough to matter.","Lasting only briefly, and meant to.","Advancing in stages, each going further than the last."]', '["wordsmith","fan-out","play it by ear","trivial","panopticon"]', 'using too many words', '["rude and unkind","spoken very quietly","full of spelling mistakes"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
