INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_unequivocal', 'unequivocal', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_unequivocal_0', 'e_unequivocal', 0, 'unequivocal', '["unequivocally"]', 'Stated so clearly that it can only be read one way.', 'Use it for statements and evidence rather than for people. If you call your own results unequivocal, others will look hard for one case that proves you wrong.', 'The board came back unequivocal on this: no client data leaves the tenancy, under any structure.', '[{"text":"You are relaying a decision from the top that came with no conditions attached, and people keep asking where the wiggle room is.","setting":"work"},{"text":"A regulator''s letter allows exactly one reading, and you are summarising it for a team that would very much like it to allow two.","setting":"work"},{"text":"Your doctor''s advice about the medication came without a single hedge, and a relative keeps hunting for the loophole.","setting":"life"},{"text":"A friend asks whether your partner is genuinely on board with the move. She said yes in a way that left nothing open.","setting":"life"}]', '["Made deliberately hard to understand.","Big enough to matter, said of an amount or a change.","Aware of something and taking it into account.","Covering a wide range of cases rather than a narrow one.","True on the whole, allowing for exceptions nobody is going to list."]', '["fan-out","advocate for","verifiable rewards","second order effects","frontrunner"]', 'completely clear', '["hard to believe","said in secret","full of small mistakes"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
