INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_surreptitiously', 'surreptitiously', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_surreptitiously_0', 'e_surreptitiously', 0, 'surreptitiously', '["surreptitious"]', 'Done quietly so that nobody sees it happening.', 'It suggests hiding on purpose, so about a colleague it reads as an accusation, and about a system it suggests a security problem. It is safest used lightly about yourself.', 'Nobody signed anything off. A team had been surreptitiously pointing production traffic at the new index for a month.', '[{"text":"You checked the football score under the table during your niece''s school play.","setting":"life"},{"text":"A friend has been moving small amounts out of the joint account for months to pay for a surprise trip.","setting":"life"},{"text":"Someone at the next table is clearly photographing the menu prices and clearly does not want to be seen doing it.","setting":"life"},{"text":"You want to describe how a team kept an old system quietly running long after it was declared dead, and you are choosing how hard to make that land.","setting":"work"}]', '["In the most prominent position, where it cannot be missed.","Directly and without hedging.","Lasting only briefly, and meant to.","Done on purpose and after thought rather than by accident.","Present in scattered, isolated places rather than across the whole."]', '["esoteric","amenable","daily driver","diaspora","persist"]', 'in a secret way', '["very slowly","in an angry way","in front of everyone"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_surreptitiously_0_recognition', 's_surreptitiously_0', 'recognition', NULL, NULL, 128, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
