INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_community_of_practice_vs_center_of_excellence', 'community of practice vs center of excellence', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_community_of_practice_vs_center_of_excellence_0', 'e_community_of_practice_vs_center_of_excellence', 0, 'community of practice', '["CoP","communities of practice"]', 'A voluntary group of people doing the same work who meet to share what they learn.', 'Membership is voluntary, so it cannot be held to a deadline or made to enforce standards. If you give it a budget and staff, call it a center of excellence instead.', 'The prompt engineering group is not a governance body. It is a community of practice, and it works precisely because nobody has to come.', '[{"text":"Engineers in four product teams keep solving the same problem separately, and you want to propose a standing forum with no mandate and optional attendance.","setting":"work"},{"text":"A director asks what to call the monthly session where people demo what they tried and what failed, and you want a name that promises sharing rather than authority.","setting":"work"},{"text":"A sponsor asks how the data scientists scattered across four teams will stay aligned when you have no authority over any of them.","setting":"work"}]', '["The most senior people in an organisation, spoken of as a single group.","A people scattered from a homeland who keep a tie to it.","A funded, staffed team that owns a standard and enforces it across other teams.","The history one organisation holds about why things were built the way that they were.","What someone can do but cannot fully explain, such as judgement, feel, or a sense of fit."]', '["dogfooding","front and center","trivial","sandbox","eschew"]', 'an informal group sharing skills', '["a funded expert team","a list of company rules","a committee that approves budgets"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
