INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_community_of_practice_vs_center_of_excellence_1', 'e_community_of_practice_vs_center_of_excellence', 1, 'center of excellence', '["CoE","centre of excellence","centers of excellence"]', 'A funded team that holds a scarce skill in one place and sets how it is done.', 'Other teams may feel they now need its permission, which causes resentment. Use it only for a funded, staffed team, since senior people notice when an unfunded group uses the name.', 'If we stand this up as a center of excellence, every model deployment routes through eight people, and those eight people are the constraint by March.', '[{"text":"Four teams have each hired one data scientist and none of them can staff a whole project. You are proposing a single funded team that serves all four and owns the standards.","setting":"work"},{"text":"A sponsor wants one accountable home for model risk, with real headcount attached, and asks what to call it in the operating model.","setting":"work"},{"text":"You are warning a steering group that routing every deployment through one specialist team will make that team the bottleneck by spring, and you want to name the pattern you are warning against.","setting":"work"}]', '["A voluntary group of practitioners who meet to trade what they are learning.","The most senior people in an organisation, spoken of as one group.","A slice of the market defined by the industry it serves, such as banking or health.","One of the handful of cloud providers operating at planetary scale.","The person who argues your case in the rooms you are not in, without being asked."]', '["elucidate","in pockets","bespoke","persistence","primitive"]', 'a funded expert team', '["an informal group sharing skills","a new office building","a staff party"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
