INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_first_principles', 'first principles', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_first_principles_0', 'e_first_principles', 0, 'first principles', '["from first principles"]', 'The basic truths you build an answer up from instead of copying how it is usually done.', 'Saying you are going back to first principles suggests past work was careless, so name the assumptions you are dropping. It is also slow, so save it for decisions that need it.', 'Before we copy the vendor''s architecture wholesale, give me one pass from first principles. What do we actually need to be true here?', '[{"text":"Everyone in the industry does it one way and nobody in the room can say why. You want to propose spending a day working the problem out from scratch instead of inheriting the answer.","setting":"work"},{"text":"A cost model has been carried forward from an old project for three years, and you want to argue for rebuilding it out of what the components cost today.","setting":"work"},{"text":"You are weighing whether to buy or rent and realise every opinion you hold about it came from your parents.","setting":"life"},{"text":"A friend''s business plan copies a competitor''s pricing to the pound. You want to suggest working out what the thing costs to make and what it is worth to a customer, before looking at anyone else''s number.","setting":"life"}]', '["A rule of thumb that gets you a good enough answer quickly.","The underlying layer everything above it runs on and takes for granted.","The direct consequences of a change, before anyone has adapted to it.","What someone can do but cannot fully explain, such as judgement, feel, or a sense of fit.","The approvals and preparation done in advance of a moment where a gap would cost you dearly."]', '["verifiable rewards","disparage","substantial","cognizant","center of excellence"]', 'the basic truths you start from', '["the latest industry trends","the steps in a project plan","the people who make final decisions"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
