INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_semantic_layer', 'semantic layer', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_semantic_layer_0', 'e_semantic_layer', 0, 'semantic layer', '["semantic model"]', 'The layer that translates raw tables into the business terms everyone agrees on.', 'The hard part is getting departments to agree on what each business term means, so do not promise one by a date. Use the term only for this specific part of a data system.', 'Two dashboards disagree on churn because each defines it in its own SQL. That is exactly what a semantic layer is for.', '[{"text":"Finance and operations arrive at the same meeting with two different revenue numbers, and both are correct against their own queries.","setting":"work"},{"text":"A director asks why self-service reporting keeps producing figures nobody trusts, and you want to name the missing piece between the warehouse and the dashboards.","setting":"work"},{"text":"You are costing a data platform and need a line item for the component that holds the business definitions in one place instead of in every tool separately.","setting":"work"}]', '["The underlying layer everything above it runs on and takes for granted.","A basic building block a platform hands you and expects you to compose with.","An isolated environment where code runs without touching anything real.","A slice of the market defined by the industry it serves, such as banking or logistics.","One of the handful of cloud providers that runs compute and storage at planetary scale."]', '["disambiguate","top brass","dogfooding","flywheel effect","fearless forecast"]', 'a shared set of data definitions', '["a tool for drawing charts","a backup copy of a database","a server that stores website images"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
