INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_heuristic', 'heuristic', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_heuristic_0', 'e_heuristic', 0, 'heuristic', '["heuristics"]', 'A quick, simple rule that is usually right but not always.', 'Calling a rule a heuristic admits it can be wrong. Do not use it to soften a number that came from real analysis, and expect to be asked where the number came from.', 'Triage runs on a heuristic today, anything over fifty thousand goes to a human, and we replace it the moment we have labelled data.', '[{"text":"You are shipping a triage rule that is really a threshold someone picked, and you want to be honest with the steering group about what it is without sinking the release.","setting":"work"},{"text":"A director asks how the system decides what to escalate, and the truthful answer is a simple rule that catches most of the cases most of the time.","setting":"work"},{"text":"A friend asks how you choose which restaurant on an unfamiliar street to walk into, and your answer is a rule that works often enough.","setting":"life"},{"text":"You always leave for the airport three hours ahead whatever the flight, and someone asks whether that is really necessary.","setting":"life"}]', '["The basic truths you reason up from once precedent has been stripped away.","What someone can do but cannot fully explain, such as judgement or feel.","A specific way that a system goes wrong.","A number given straight, with the caveats stripped out.","Training signal a machine can check for itself rather than a person judging it."]', '["lean on","build that muscle","sandbox","unequivocal","substrate"]', 'a quick rule that usually works', '["a proven law of science","a detailed written plan","a formal agreement between companies"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_heuristic_0_recognition', 's_heuristic_0', 'recognition', NULL, NULL, 160, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_heuristic_0_identify', 's_heuristic_0', 'identify', NULL, NULL, 161, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
