INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_scaffolding_harness_sandbox', 'scaffolding/harness/sandbox', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_scaffolding_harness_sandbox_0', 'e_scaffolding_harness_sandbox', 0, 'scaffolding', '["scaffold"]', 'A temporary support that is removed once the real system works on its own.', 'It tells people the thing is temporary, and they will later ask when it is being removed. For a rough first version of the real work, say draft instead.', 'The manual review step is scaffolding. Once the classifier is calibrated it comes out.', '[{"text":"You hardcoded a lookup to unblock a demo and want your tech lead to know it is not meant to survive.","setting":"work"},{"text":"A sponsor asks why an automated pipeline still has a person sitting in the middle of it.","setting":"work"},{"text":"A friend is propping up a bookshelf with a stack of magazines until the brackets arrive.","setting":"life"},{"text":"You are running alongside your daughter''s bike with a hand under the saddle, and someone asks how long you plan to keep doing that.","setting":"life"}]', '["An isolated environment where code runs without touching anything real.","A rig that drives a system from outside to see how it behaves.","Lasting only briefly, and created for one use before being thrown away.","A basic building block a platform hands you and expects you to compose things out of.","The preparation done in advance of a moment where a gap would cost you dearly."]', '["disparage","ducks in a row","long-horizon","heuristic","vertical"]', 'a temporary support', '["a backup copy","a list of known bugs","a safe, isolated test area"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
