INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_scaffolding_harness_sandbox_0_production', 's_scaffolding_harness_sandbox_0', 'production', NULL, NULL, 167, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_scaffolding_harness_sandbox_1', 'e_scaffolding_harness_sandbox', 1, 'harness', '[]', 'A setup built to run a system automatically and check how it behaves.', 'In AI work people usually hear evaluation harness, so say so if you mean a general test setup. Use it for tools you built yourself, and not for a public benchmark you only ran.', 'We need a harness that replays last quarter''s queries against the new model.', '[{"text":"You want something that fires realistic inputs at your agent and records what comes back, so you can compare two versions honestly.","setting":"work"},{"text":"A director asks how you will know the new model is better, and you need a word for the apparatus that answers that.","setting":"work"},{"text":"A vendor demo went well and you want to run your own inputs through their system under your own conditions before believing any of it.","setting":"work"}]', '["Temporary structure that holds work up until the real thing can stand alone.","An isolated environment where something runs without affecting anything real.","Using your own product for real work before asking anyone else to.","A specific way a system goes wrong.","The underlying layer everything else runs on."]', '["lay of the land","squarely","enmeshed","verifiability","tacit knowledge"]', 'a setup for testing a system', '["a temporary support","a list of user complaints","a contract with an outside vendor"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
