INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_scaffolding_harness_sandbox_1_production', 's_scaffolding_harness_sandbox_1', 'production', NULL, NULL, 171, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_scaffolding_harness_sandbox_2', 'e_scaffolding_harness_sandbox', 2, 'sandbox', '["sandboxed"]', 'An isolated place to run something where it cannot affect anything real.', 'It promises that nothing real can be affected, and compliance teams will hold you to that. It says nothing about how realistic the setup is.', 'Let it run in a sandbox first. I do not want it touching the live index.', '[{"text":"You are letting an agent execute code it wrote itself and want somewhere it cannot do damage.","setting":"work"},{"text":"Compliance asks what stops the new tool reading customer records during testing.","setting":"work"},{"text":"A vendor wants their engineers to try your pipeline, and you need a word for the walled-off copy you are willing to give them.","setting":"work"}]', '["Temporary structure that holds work up until the real thing can stand alone.","A rig that drives a system from outside to see how it behaves.","Present in scattered, isolated places rather than across the whole.","Using your own product for real work before you ask anyone else to.","One of the handful of cloud providers running compute and storage at planetary scale."]', '["heuristic","deliberate","daily driver","first principles","mold breaker"]', 'a safe, isolated test area', '["a temporary support","a shared team calendar","the live production system"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_scaffolding_harness_sandbox_2_recognition', 's_scaffolding_harness_sandbox_2', 'recognition', NULL, NULL, 172, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
