INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_persist_persistence', 'persist/persistence', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_persist_persistence_0', 'e_persist_persistence', 0, 'persist', '["persisted","persisting"]', 'To save data somewhere it will survive a restart or a refresh.', 'Engineers hear a promise that the data will survive a crash, so do not use it for data held only in memory. With non-technical people, say save instead.', 'Right now the session only lives in memory. If the pod restarts we lose the whole conversation, so we need to persist it.', '[{"text":"A prototype loses everything the user typed the moment the browser is refreshed, and you are writing the ticket for what has to change.","setting":"work"},{"text":"In a design review someone is holding session state in memory on a single node, and you want to name the missing property before it goes near production.","setting":"work"},{"text":"An architect asks where the agent''s conversation history lives after a pod restarts, and you want the verb for putting it somewhere that survives one.","setting":"work"}]', '["To turn an object in memory into bytes that can be sent over a wire.","To replace a running component without stopping the system around it.","To make a bad situation worse.","To avoid something deliberately and on principle.","To settle which of two possible readings is the one meant."]', '["enmeshed","run it by you","inroads","scaffolding","disparage"]', 'to save data permanently', '["to send a message","to delete old files","to check data for mistakes"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
