INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_persist_persistence_0_production', 's_persist_persistence_0', 'production', NULL, NULL, 179, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_persist_persistence_1', 'e_persist_persistence', 1, 'persistence', '["persistent"]', 'Staying with something long after most people would have stopped.', 'Praising persistence suggests the person succeeded by not stopping, which can seem a weak compliment for good work. Calling someone persistent often means they will not take no.', 'That deal closed on persistence more than anything else. She went back to them four times after we had all written it off.', '[{"text":"A friend got into medical school on their third application, and you are raising a glass to whatever it was that got them there.","setting":"life"},{"text":"Your son has been failing the same climbing route every Saturday for a month, and today he got up it.","setting":"life"},{"text":"You are writing a reference for someone whose strongest quality is that they never let a thing drop.","setting":"work"},{"text":"A neighbour finally got the council to replace the broken streetlight after a year of letters nobody answered.","setting":"life"}]', '["Weight and seriousness in how a person carries themselves.","Being aware of something and visibly taking it into account.","Tangled into something so completely that you can no longer act on your own.","Low in a way that has given up on things improving.","Alert and responsive to something, picking up its signals early and adjusting."]', '["bolster","blanket approval","failure mode","surreptitiously","north star"]', 'refusing to give up', '["fear of failing","lack of interest","great natural talent"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
