INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_primitive', 'primitive', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_primitive_0', 'e_primitive', 0, 'primitive', '["primitives"]', 'A basic building block a platform gives you to build bigger things out of.', 'Outside technical rooms people hear the everyday meaning, crude or backward, so it can insult a team''s tools. Among engineers it claims the piece is the right size to build on.', 'Give the teams three primitives, retrieval, evaluation and identity, and let them assemble the workflow they actually need.', '[{"text":"You are arguing against shipping ten finished workflows and for shipping a few small pieces that teams combine themselves, and you need the word for those pieces.","setting":"work"},{"text":"A platform review asks what your team actually offers everyone else, and the honest answer is four small capabilities that everything else is assembled from.","setting":"work"},{"text":"A colleague proposes one API call that authenticates, retrieves and logs, and you want to argue for three separate things a team can combine as they like.","setting":"work"}]', '["The underlying layer everything above it runs on and takes for granted.","Built for one customer or one case rather than taken off the shelf.","A set that contains everything another one contains, and more.","The place where raw tables are mapped onto the words the business actually uses.","Temporary structure that holds work up until the real thing can stand on its own."]', '["persist","lay of the land","watch outs","modality","gravitas"]', 'a basic piece to build with', '["a security warning","a monthly usage report","a finished software product"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_primitive_0_recognition', 's_primitive_0', 'recognition', NULL, NULL, 184, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
