INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_serialize', 'serialize', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_serialize_0', 'e_serialize', 0, 'serialize', '["serialization","serialized","serialise"]', 'To turn something in memory into bytes that can be stored or sent and read back.', 'In performance talk it also means forcing tasks to run one at a time, so name the format or the bottleneck. With non-technical people, say you save it in a form you can send.', 'The agent state has to be serialized before it goes on the queue, and half of these objects have no clean way to do that.', '[{"text":"An object holding your agent''s working state needs to go onto a message queue, and you are explaining what has to happen to it before it can.","setting":"work"},{"text":"Two services written in different languages need to exchange the same structure, and you are choosing the format both of them will write and read.","setting":"work"},{"text":"A trained model has to be written to a file so that another process can load it back in exactly the shape it was.","setting":"work"}]', '["To replace a running component without stopping the system around it.","To split one request into many branches that run at the same time.","To avoid something deliberately and on principle.","A kind of input or output a system works in, such as text, images, audio, or video.","To make something deliberately hard to understand so the plain version stays hidden."]', '["incremental","superset","verifiability","lend itself","dogfooding"]', 'to convert data for storage', '["to delete old records","to speed up a program","to split work across machines"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
