INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_broad', 'broad', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_broad_0', 'e_broad', 0, 'broad', '["broadly"]', 'Covering a wide range of cases or topics rather than a narrow one.', '''Broad support'' hints that some people disagree, so expect to be asked who. As a noun it is old, offensive slang for a woman.', 'There''s broad support from the business, though procurement still has questions about the licensing.', '[{"text":"Your sponsor asks whether the other directors are behind the platform plan. Most are, one is not, and you want an adjective that is honest without opening that up in this meeting.","setting":"work"},{"text":"A steering committee asks about the new team''s remit. It reaches into every business unit rather than one specialism, and you want a word for how wide that is.","setting":"work"},{"text":"A director catches you in the corridor and asks for the shape of next year''s roadmap. You can give the outline but not the specifics, and you want to signal that as you start.","setting":"work"},{"text":"A friend asks what a mutual acquaintance is actually good at. She does many things capably rather than one thing brilliantly, and you mean that as praise.","setting":"life"},{"text":"You are choosing a film for a group with very different tastes and want a word for something with wide appeal rather than something you personally love.","setting":"life"}]', '["Built for one customer rather than taken off the shelf.","Lasting only a short time, and meant to.","Safe to run more than once, because a repeat run changes nothing.","Present only in scattered places instead of everywhere across the organisation.","Using far more words than the point actually needs, in speech or on the page."]', '["front and center","scaffolding","obscure","inroads","ducks in a row"]', 'covering many things', '["easy to ignore","badly out of date","happening very slowly"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
