INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_modality', 'modality', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_modality_0', 'e_modality', 0, 'modality', '["modalities"]', 'A kind of input or output a system works in, such as text, images, audio or video.', 'In AI talk it means a type of data, such as text or images. Avoid it where ''format'' or ''channel'' would do, because it sounds inflated and other fields read it differently.', 'The hard part isn''t the volume, it''s that the filings arrive in three modalities and only one of them is clean text.', '[{"text":"A sponsor asks why letting the assistant accept voice is not a small change. You want the term for the kind of input, so you can say the pipeline handles exactly one of them today.","setting":"work"},{"text":"You are writing an evaluation plan and need one heading that covers text, images and audio together as a single category of thing.","setting":"work"},{"text":"A colleague argues the product should answer in speech as well as on screen. You want one word for what they are proposing to add, rather than a list.","setting":"work"},{"text":"You are explaining to your father why his phone can now answer a question about a photograph as well as a typed question, and you want the word for those different kinds of input.","setting":"life"}]', '["A rule of thumb that gets you a good enough answer quickly.","The place where raw tables and columns are mapped onto words the business uses.","Temporary structure that holds work up until the real thing can stand on its own.","One of the handful of cloud providers running compute and storage at planetary scale.","A people scattered from a homeland who keep a tie to it, and that scattering itself."]', '["bespoke","superset","hyperscaler","attuned","heuristic"]', 'a type of input or output', '["a step in a process","a measure of accuracy","a place where data is kept"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
