INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_frontier', 'frontier', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_frontier_0', 'e_frontier', 0, 'frontier', '["frontier model","frontier models","frontier lab","frontier labs"]', 'The current edge of what AI systems can do, and the labs and models working there.', 'Keep it for the most capable labs and models. Experts will correct you if you use it for your own work, and the claim goes out of date quickly.', 'We aren''t building at the frontier. We''re building on top of it, and that''s a completely different risk profile.', '[{"text":"An MD asks whether the supplier''s system is genuinely in the top tier of what exists or just the most recently announced, and you need the word for that tier.","setting":"work"},{"text":"You are drafting a risk note about depending on the very small number of organisations whose systems define what is currently possible, and you want the one-word label the industry uses for them.","setting":"work"},{"text":"You are arguing that a capability which only exists in research today will be ordinary in eighteen months, and you need a term for where it sits right now.","setting":"work"},{"text":"A friend outside the industry asks who is actually ahead in AI. You want the term for the handful of outfits at the edge of what is possible, rather than reciting company names.","setting":"life"}]', '["A funded team that concentrates a scarce skill in one place and sets how it is used.","The most senior people in an organisation, spoken of as a single group.","Deep structural change in the conditions everyone is operating under.","An isolated environment where a system can run without being able to affect anything real.","The short list of things most likely to go wrong, handed to someone before they start."]', '["scaffolding","trivial","lend itself","persistence","rectify"]', 'the most advanced AI models', '["the cheapest AI option","an old, retired AI system","a public ranking of AI tests"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
