INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_wordsmith', 'wordsmith', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_wordsmith_0', 'e_wordsmith', 0, 'wordsmith', '["wordsmithing","wordsmithed","wordsmiths"]', 'To reword a draft so it reads better without changing what it says.', 'It is fine about your own draft. Calling someone else''s change ''just wordsmithing'' dismisses it as cosmetic, which is unfair if their point was real.', 'The recommendation is agreed. Give me an hour to wordsmith it before it goes to the committee.', '[{"text":"Your manager has approved what the memo argues but the sentences are clumsy. You want to offer to fix how it reads without reopening the argument.","setting":"work"},{"text":"In a review, a colleague keeps proposing small changes to how a paragraph reads while the actual decision is still unresolved, and you want a name for what the meeting has turned into.","setting":"work"},{"text":"You are helping a friend tighten a wedding speech. The content is entirely theirs and you are only working on how each line lands.","setting":"life"},{"text":"You have drafted a difficult message to a family member and want to spend twenty minutes on exactly how each sentence reads before you send it.","setting":"life"}]', '["To make something deliberately hard to understand.","To make a bad situation worse than it already was.","To turn a structure held in memory into a form that can be stored or sent.","To use your own product for real work before you ask anyone else to use it.","To speak about someone in a way that quietly lowers them."]', '["first order effects","continuum","play it by ear","top brass","watch outs"]', 'to improve the wording', '["to check the facts","to write from scratch","to translate into English"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
