INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_long_horizon_task', 'long-horizon (task)', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_long_horizon_task_0', 'e_long_horizon_task', 0, 'long-horizon', '["long horizon","long-horizon task","long horizon task","long-horizon tasks"]', 'Running for many steps before anyone can tell whether it worked.', 'Use it for tasks with many steps and slow feedback. For a project that is only slow, say slow, since investors may hear it as a holding period.', 'Single-shot extraction is basically solved. The long-horizon work - chase the filing, reconcile it, come back with a memo - is where it still falls over.', '[{"text":"You are explaining to a director why an agent that answers questions well still cannot be trusted with a whole reconciliation end to end, and you need the term for the second kind of work.","setting":"work"},{"text":"In an evaluation design meeting you need a name for the category of test where the system only discovers at the very end whether it got there.","setting":"work"},{"text":"A supplier demos an agent completing a task in three steps and claims it generalises. You want the term for the class of work their demo never touched.","setting":"work"},{"text":"A sponsor asks why one task of forty steps is harder for a system than forty tasks of one step, and you want the standard term for the first kind.","setting":"work"}]', '["Safe to run more than once, since the second run leaves things exactly as the first did.","Understood by only a small group, because it assumes background that most people lack.","Built for one customer rather than taken off the shelf.","Lasting only briefly, and meant to.","So small or so easy that it is not worth the time it would take to discuss."]', '["hot-swap","surreptitiously","bespoke","build that muscle","tectonic shift"]', 'needing many steps to finish', '["easy to check quickly","costing a lot of money","built by more than one company"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
