INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_enmeshed', 'enmeshed', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_enmeshed_0', 'e_enmeshed', 0, 'enmeshed', '["enmesh","enmeshment","enmeshing"]', 'Tangled up with something so tightly that the two can no longer act separately.', 'It comes from family therapy and says a relationship is unhealthy. For systems that simply depend on each other, say tightly coupled.', 'Support and engineering aren''t collaborating, they''re enmeshed - neither one can plan a quarter without the other in the room.', '[{"text":"You are describing a friend whose life has folded so completely into their partner''s that they no longer seem to hold separate opinions about anything.","setting":"life"},{"text":"A cousin''s business and their marriage have grown into each other to the point that neither can be sorted out without the other, and you want one word that is honest about the trouble in it.","setting":"life"},{"text":"Two teams can no longer plan a quarter, hire or ship without the other in the room, and you want a word that signals this has gone past healthy collaboration.","setting":"work"},{"text":"You are writing about a supplier relationship where your processes and theirs have grown together so far that leaving would mean rebuilding the business, and you need something stronger than dependent.","setting":"work"}]', '["Present in scattered, isolated places rather than across the whole.","Open to something without having agreed to it yet.","Safe to run more than once, because repeat runs change nothing.","An isolated environment where something runs without being able to affect anything real.","A people scattered from a homeland who keep a tie to it, and the fact of that scattering."]', '["frontier","contrived","tacit knowledge","verifiable rewards","sleuthing"]', 'too closely tied together', '["kept completely apart","slow to respond to requests","badly out of date"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
