INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_eschew', 'eschew', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_eschew_0', 'e_eschew', 0, 'eschew', '["eschews","eschewed","eschewing"]', 'To deliberately avoid something you could have chosen, usually on principle.', 'It is a written word and sounds stiff when spoken. It also suggests a principle, so if the real reason was budget or timing, say ''chose not to use''.', 'The paper eschews benchmark scores entirely and reports only task completion, which is either brave or very convenient.', '[{"text":"You are writing about a research group that left benchmark numbers out of a paper on purpose, and you want a verb that makes clear it was a choice rather than an oversight.","setting":"work"},{"text":"In an architecture note you want to record that the team turned down managed services as a matter of principle, not because of what they cost.","setting":"work"},{"text":"A friend has given up social media entirely and it is a stance rather than a lapse. You are writing about them and want the verb that honours the difference.","setting":"life"},{"text":"You are describing a novelist who refuses to write any dialogue at all, and you want a word that treats the refusal as deliberate craft.","setting":"life"}]', '["To make a bad situation worse than it already was.","To put right something that was wrong, such as an error or an imbalance.","To back a claim with evidence that someone else can check for themselves.","To turn a structure that only exists in memory into something you can store or send.","To replace a running part of a system without stopping the system around it."]', '["exacerbate","despondent","broad","run it by you","incremental"]', 'to avoid on purpose', '["to accept gladly","to explain in detail","to put off until later"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
