INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_attuned', 'attuned', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_attuned_0', 'e_attuned', 0, 'attuned', '["attune","attuning","attunement"]', 'Alert to something and quick to pick up small signals from it and adjust.', 'Use it to praise someone else. Saying it about yourself sounds boastful, and in AI talk people may hear ''tuned'' and think of a trained model.', 'She''s attuned to when a sponsor has gone quiet for political reasons rather than practical ones.', '[{"text":"You are recommending someone for a client-facing role because they notice when a room has cooled before anybody has said a thing.","setting":"work"},{"text":"A colleague keeps missing that the sponsor''s silences are political rather than practical, and you want to name the quality they are short of without insulting them.","setting":"work"},{"text":"You are describing a friend who can tell within a minute of sitting down that two people at the table have had an argument.","setting":"life"},{"text":"Your partner rearranges the day around your mood before you have said anything about it, and you want the word for what they are doing.","setting":"life"}]', '["Low in a way that has given up on things getting better.","Admitting only one reading, so nobody can take it two ways.","Done quietly so that nobody sees it being done.","Understood by only a small group, because it assumes background that most people lack.","A rule of thumb that gets you a good enough answer quickly, because it usually works."]', '["superset","buy-in","institutional knowledge","substantiate","frontrunner"]', 'sensitive to small signals', '["slow to make decisions","strict about following rules","proud of past success"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
