INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_run_it_by_you', 'run it by you', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_run_it_by_you_0', 'e_run_it_by_you', 0, 'run it by you', '["run it past you","run this by you","run that by you","run something by you","run it by someone","running it by you","run it by him","run it by her","run it by them"]', 'To show someone something before committing to it, to hear their reaction.', 'It suggests you could go ahead without them. That is polite with a boss or peer, but with someone whose approval you need it can play down their role.', 'Before I send this to the MD, can I run it by you?', '[{"text":"You have drafted a recommendation and want your manager''s reaction before it goes further, without making it a formal approval request.","setting":"work"},{"text":"You are about to propose a change touching another team''s system and want to show their lead first as a courtesy.","setting":"work"},{"text":"You are planning a surprise for your partner and want to check the idea with their sibling before booking anything.","setting":"life"},{"text":"You have chosen a restaurant for a group dinner and want to float it with one of them before committing everyone.","setting":"life"}]', '["To make something deliberately hard to understand so the plain version stays out of reach.","To settle which of two possible readings is the one that was meant.","To write something down somewhere it will outlive whatever made it.","To use your own product for real work before you ask anyone else to use it.","To speak about someone in a way that lowers them, usually in passing."]', '["play it by ear","substrate","sandbox","hot-swap","second order effects"]', 'to check an idea with someone', '["to hand work to someone else","to reschedule a planned meeting","to complain to a manager"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
