INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_play_it_by_ear', 'play it by ear', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_play_it_by_ear_0', 'e_play_it_by_ear', 0, 'play it by ear', '["playing it by ear","played it by ear","play things by ear","play that by ear","play the rest by ear"]', 'To decide as you go, guided by what actually happens rather than by a set plan.', 'It admits there is no plan. That sounds relaxed with friends but unprepared to a sponsor, so say what information you are waiting for.', 'We''ll fix the first two milestones and play the rest by ear until the vendor confirms their dates.', '[{"text":"A friend asks what time you will get to the party and whether you are staying for dinner, and you would rather not commit to either.","setting":"life"},{"text":"You are going to a city for two days with nothing booked past the first night, and a relative asks for your itinerary.","setting":"life"},{"text":"A director asks how you intend to handle the questions in a session where you do not yet know who is attending or what mood they will be in.","setting":"work"},{"text":"The supplier has not confirmed their dates, so the second half of the plan cannot be fixed yet, and you need a way to say so that does not sound unprepared.","setting":"work"}]', '["To put right something that has gone wrong.","To avoid something on purpose, having had the option to take it.","A rule of thumb that gets you a good enough answer quickly, because it usually works.","The preparation you do in advance of a moment where any gap would cost you.","Temporary structure that holds the work up until the real thing can stand on its own."]', '["lay of the land","finesse","executive presence","gravitas","long-horizon"]', 'to decide as you go', '["to follow a fixed plan","to stop work early","to ask for more money"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
