INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_advocate', 'advocate', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_advocate_0', 'e_advocate', 0, 'advocate', '["advocates"]', 'A person who argues for you when you are not there.', 'Naming someone as your advocate gives them a job they may not have agreed to, and can expose them in front of peers. Lawyers hear it as meaning legal counsel.', 'We don''t need everyone convinced. We need one advocate on that committee who''ll say it when we''re not in the room.', '[{"text":"You are told the committee will decide without you present, and you want the word for the one person in there who will make your case.","setting":"work"},{"text":"A mentor asks what you actually need from her, and the honest answer is someone who will speak for the work when you are not there to speak for it.","setting":"work"},{"text":"Your grandmother''s hospital appointments go badly when she attends alone, and you want the word for the role a family member plays by going with her.","setting":"life"},{"text":"You are describing a teacher who fought the school on your son''s behalf for two years, and you want the word for what she was to him.","setting":"life"}]', '["The most senior people in an organisation, spoken of as one group.","A voluntary group of people who do the same work and swap what they know.","A rule of thumb that usually works well enough.","An isolated environment where code runs safely.","The one you actually use every day."]', '["elucidate","community of practice","rectify","bespoke","tectonic shift"]', 'someone who speaks up for you', '["someone who checks your work","a new member of a team","someone who pays for a project"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
