INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_advocate_1', 'e_advocate', 1, 'advocate for', '["advocate","advocating","advocating for","advocated for","advocacy"]', 'To argue openly for a position or a person, putting your reputation at risk.', 'It ties you to the outcome, so keep it for things you would still defend if they failed. If all you did was agree in a meeting, do not claim it.', 'I advocated for keeping the evaluation in-house, and knowing what it cost us, I''d make the same call again.', '[{"text":"In a performance conversation you need a verb for the handful of times you put your own name behind an unpopular position rather than simply agreeing with it.","setting":"work"},{"text":"A junior colleague''s work was passed over and you intend to raise it with the panel yourself, at some cost to your own standing.","setting":"work"},{"text":"You are pressing the council to fix a dangerous junction by the school, and it has turned into a campaign rather than a complaint.","setting":"life"},{"text":"A relative needs a treatment the insurer keeps refusing, and somebody in the family has to make the case, loudly and repeatedly.","setting":"life"}]', '["To speak about someone in a way that lowers them, usually with a passing remark.","To make a bad situation worse.","To avoid something on purpose when you could have taken it.","To make something already written finally make sense by laying out the reasoning.","To turn a structure that only exists in memory into a form you can store or send on."]', '["hyperscaler","verifiability","contrived","top brass","frontrunner"]', 'to publicly support', '["to argue against","to ask questions about","to keep quiet about"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
