INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_frontrunner', 'frontrunner', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_frontrunner_0', 'e_frontrunner', 0, 'frontrunner', '["front-runner","front runner","frontrunners","front-runners"]', 'The one most likely to win right now, while the outcome is still open.', 'Naming one in writing before a decision makes the process look decided, which can cause trouble in a procurement challenge. Keep it to conversation.', 'Off the record the Swiss vendor is the frontrunner, but nothing goes in writing until scoring closes.', '[{"text":"Two candidates are left for a director role and one is clearly ahead. You are saying so to a peer over coffee, not putting it in an email.","setting":"work"},{"text":"A sponsor asks which supplier is likely to win while the scoring is still open, and you want a word that reports a position without announcing a decision.","setting":"work"},{"text":"Friends are arguing about who takes over as captain next season, and one name is obviously ahead of the others.","setting":"life"},{"text":"You and your partner have seen six flats and one is well ahead of the rest, though nothing is decided and you may still see more.","setting":"life"}]', '["The one you actually use every day, as opposed to the one kept for special cases.","A funded team that concentrates a scarce skill in one place and sets how it is used.","Weight and seriousness in how a person carries themselves.","A rule of thumb that usually works.","The most senior people in an organisation."]', '["advocate","failure mode","eschew","continuum","surreptitiously"]', 'the one most likely to win', '["the newest competitor","the person who runs a meeting","a backup option"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
