INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_build_that_muscle', 'build that muscle', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_build_that_muscle_0', 'e_build_that_muscle', 0, 'build that muscle', '["build the muscle","building that muscle","build this muscle","built that muscle","build that muscle up","build muscle"]', 'To build a skill through repeated practice instead of one-off training.', 'It says the skill is missing today. About another team it is a criticism, and to a busy team it means more work, so name the actual practice and who will do it.', 'We can buy the first three evaluations in. If we want this capability in-house, at some point we have to build that muscle ourselves.', '[{"text":"Your team keeps handing evaluation work to a consultancy, and you want to argue for doing it in-house repeatedly until they are good at it.","setting":"work"},{"text":"A director asks why you are giving juniors the client presentations when a senior would do a better job today, and your answer is about where the team is in a year.","setting":"work"},{"text":"A friend says they are simply hopeless at cooking, and you want to say the ability is not fixed and comes from doing it over and over.","setting":"life"},{"text":"You have started running twice a week and are explaining to a sceptical relative why the first month feeling awful is the whole point.","setting":"life"}]', '["To use your own product for real work before asking anyone else to.","To make a bad situation worse than it already was.","To dig patiently through records for something that was never hidden on purpose.","To replace a running part of a system without stopping the system around it.","To put right something that was wrong."]', '["nontrivial","persist","pick your brain","sleuthing","institutional knowledge"]', 'to develop a skill by practice', '["to buy a ready-made tool","to cut a team''s workload","to measure a team''s performance"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
