INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_tacit_institutional_knowledge', 'tacit/institutional knowledge', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_tacit_institutional_knowledge_0', 'e_tacit_institutional_knowledge', 0, 'tacit knowledge', '["tacit"]', 'What someone can do well but cannot fully put into words.', 'Use it only for skill that is truly hard to write down. A deployment process is just steps, so calling it tacit sounds like an excuse.', 'The runbook covers the steps. What Priya has is tacit - she can tell from the shape of the latency graph that it''s the index, not the model.', '[{"text":"Your best engineer can tell from the shape of a graph which layer is failing and cannot say how she does it. You are explaining to a director why more documentation will not transfer that.","setting":"work"},{"text":"A consultant proposes capturing everything the team has in their heads into a wiki, and you want the term for the part that will not survive the transfer.","setting":"work"},{"text":"You are describing how your mother cooks: no recipe, everything adjusted by feel, and no useful answer when you ask her for quantities.","setting":"life"},{"text":"A friend has driven the same route for two decades and anticipates every junction on it, and you want a word for what they have that a map does not hold.","setting":"life"}]', '["Deep structural change in the conditions everyone works under.","The most senior people in an organisation, spoken of as a single group.","A rule of thumb that usually works.","An isolated environment where code runs safely.","Progress won into territory that was closed to you before."]', '["top brass","superset","bespoke","bolster","fearless forecast"]', 'a skill you cannot easily explain', '["an organisation''s unwritten history","a written set of steps","a formal training course"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
