INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_tacit_institutional_knowledge_1', 'e_tacit_institutional_knowledge', 1, 'institutional knowledge', '["institutional memory"]', 'What an organisation knows about its own past and habits but has never written down.', 'It is usually an argument for keeping someone, and it can admit you let one person become a risk. It can be written down, so expect to be asked why it has not been.', 'When Martin goes we lose the institutional knowledge of why the reconciliation runs at four in the morning, and not one line of it is written down.', '[{"text":"A colleague who has been here since before the merger retires in March, and nobody else can say why half the exceptions in the billing system exist.","setting":"work"},{"text":"A new director asks why a job runs at four in the morning, and the reason is a decision taken in 2014 that only two people still remember.","setting":"work"},{"text":"You are making the case for a proper handover budget, and the thing at risk is history held in people''s heads rather than any skill you could hire for.","setting":"work"},{"text":"The committee at your sports club has turned over completely and no one left can say why the fixtures are arranged the way they are.","setting":"life"}]', '["A basic building block a platform hands you and expects you to compose with.","The one outcome you steer by while everything else stays negotiable.","A structure where everyone can be watched at any moment and nobody knows when.","One of the handful of cloud providers operating at a size where compute is effectively unlimited.","A voluntary group of people who do the same kind of work and meet to trade what they know."]', '["contrived","flywheel effect","cognizant","gravitas","nontrivial"]', 'an organisation''s unwritten history', '["skill you cannot easily explain","a new employee''s training plan","a public report on company finances"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
