INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_inroads', 'inroads', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_inroads_0', 'e_inroads', 0, 'inroads', '["make inroads","making inroads","inroad"]', 'Progress made into a market, account or group that was closed to you before.', 'It admits the other side still says no. It also treats them as opponents, which can sound hostile when they never resisted you.', 'We''ve made real inroads with the risk function, but nobody there is signing anything this quarter.', '[{"text":"A sponsor asks how the push into the private markets business is going. Two teams out of eleven are using the platform, and you want a word that is honestly partial.","setting":"work"},{"text":"You are writing a quarterly update about a department that ignored you for a year and has finally started taking meetings.","setting":"work"},{"text":"A director asks whether the backlog of data quality issues is shrinking. It is, slowly, and you do not want to claim victory.","setting":"work"},{"text":"You have been learning to swim properly after years of avoiding it, and a friend asks how it is going.","setting":"life"},{"text":"A relative who has been cold with you for years has started returning calls, and you are telling a friend where things stand.","setting":"life"}]', '["Permission given once and in advance to cover a whole class of later decisions.","The preparation done in advance of a moment where any gap would cost you dearly.","Real agreement from the people whose cooperation the work needs, not just their nods.","A rule of thumb that is quick and usually good enough.","To avoid something on principle when you could have taken it."]', '["progressive","long-horizon","by and large","verbose","sponsorship"]', 'a first success with new customers', '["a sudden loss of support","a formal agreement between two firms","a written plan for the year"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
