INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_hot_swap', 'hot-swap', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_hot_swap_0', 'e_hot_swap', 0, 'hot-swap', '["hot swap","hot-swapping","hot-swappable"]', 'To replace a running part without stopping the system around it.', 'It promises no downtime, and people will hold you to that. Said about a person, it treats people as interchangeable, which sounds cold in front of their manager.', 'The provider sits behind an interface, so we can hot-swap the model without the application knowing.', '[{"text":"You are arguing the vendor contract is not a lock-in risk, because the provider sits behind an interface and can be exchanged without the application noticing.","setting":"work"},{"text":"An architect asks how you plan to move to the new embedding model without a maintenance window.","setting":"work"},{"text":"A sponsor asks what actually happens if the API you depend on doubles its price next quarter.","setting":"work"},{"text":"Someone on-call asks whether replacing the failed node means taking the cluster down first.","setting":"work"}]', '["To turn a structure that only exists in memory into bytes that can be stored or sent.","To make something deliberately hard to understand so the plain version stays hidden.","An isolated environment where something runs without being able to affect anything real.","To put right something that was wrong.","Low in a way that has given up on things improving."]', '["build that muscle","diaspora","pick your brain","fearless forecast","exacerbate"]', 'to replace while still running', '["to shut down for repairs","to copy data to a backup","to move data between two servers"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
