INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_tectonic_shifts', 'tectonic shifts', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_tectonic_shifts_0', 'e_tectonic_shifts', 0, 'tectonic shift', '["tectonic shifts"]', 'A huge, lasting change in the basic conditions of a field or market.', 'Use it only for large, lasting change. Senior readers distrust it, because people often use it for ordinary news.', 'The interesting thing isn''t this quarter''s numbers, it''s the tectonic shift in what clients now assume we''ll automate.', '[{"text":"You are opening a board update and want to frame three years of movement in client expectations as structural rather than a trend.","setting":"work"},{"text":"A sponsor keeps reacting to competitor announcements and you want to redirect him to the slower change underneath them.","setting":"work"},{"text":"You are writing a strategy memo about how the collapsing cost of inference has changed what is worth building at all.","setting":"work"},{"text":"A friend''s industry has changed so much since he trained for it that the job is not the same job, and you want a word for that scale of change.","setting":"life"},{"text":"You are describing to family how differently your city has come to feel over a decade.","setting":"life"}]', '["Proceeding by small additions, each one small enough to stand and be judged on its own.","The one outcome a team steers by, held fixed while everything else stays negotiable.","A rig that exercises a system from outside to see how it behaves under conditions you pick.","Using far more words than the point needs.","Aware of something and visibly taking it into account."]', '["hot-swap","amenable","first principles","build that muscle","progressive"]', 'a huge, lasting change', '["a short, sudden panic","a small, routine update","a gradual loss of trust"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
