INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_first_second_order_effects_1', 'e_first_second_order_effects', 1, 'second order effects', '["second-order effects","second order effect","second-order effect"]', 'The later results that follow once people and systems adapt to the first change.', 'People often use it to block other people''s ideas. If you raise it, be ready to name one, or you only add doubt.', 'The second order effect is the one I''d watch: once reviewers trust the tool, they stop reading the diffs.', '[{"text":"A proposal will obviously save time, and your worry is what people will quietly stop doing carefully once it does.","setting":"work"},{"text":"You are asking a team to think past the immediate benefit of a new incentive to how people will behave once they work out how it is measured.","setting":"work"},{"text":"In a risk review you want the phrase for harm that only appears after everyone has adapted to the new system.","setting":"work"},{"text":"A road near you is being widened, and you want the phrase for how traffic tends to grow to fill it.","setting":"life"},{"text":"A friend describes a rule their building introduced, and you want the term for what residents promptly started doing to get around it.","setting":"life"}]', '["The place where raw tables and columns are mapped onto the words the business uses.","A funded, staffed team that concentrates a scarce skill in one place and sets how it works.","Temporary structure that holds work up until the real thing can stand without it.","To work over the exact phrasing of something already drafted.","The most senior people in a firm, spoken of as one group."]', '["tacit knowledge","disparage","failure mode","squarely","hyperscaler"]', 'the later, indirect results', '["the direct, immediate results","the main goals of a plan","the reasons a decision was made"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
