INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_contrived', 'contrived', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_contrived_0', 'e_contrived', 0, 'contrived', '["contrivance"]', 'Obviously arranged to give a particular impression, and unconvincing because of it.', 'It judges motive, so calling a colleague''s demo contrived accuses them of faking the evidence. If you only mean the example is too neat to prove much, say unrepresentative.', 'That benchmark is contrived — the questions were written after we knew what the model was good at.', '[{"text":"A vendor demo ran perfectly on inputs that were plainly chosen to make it run perfectly, and you are telling your own team why you are unconvinced.","setting":"work"},{"text":"You are reviewing an evaluation set that was written after the fact to suit the system being measured.","setting":"work"},{"text":"A business case rests on a scenario nobody believes will happen, assembled so the numbers land where they needed to.","setting":"work"},{"text":"A film''s ending only works because every character suddenly behaves unlike themselves, and you are explaining to a friend why it fell flat.","setting":"life"},{"text":"A post about a spontaneous moment is very obviously staged, and you want the word for why it irritates you.","setting":"life"}]', '["Understood by only a small group, because it assumes background that most people lack.","Handling something delicate so smoothly that the difficulty never shows to anyone else.","Advancing in stages, with each stage reaching further than the one before it.","Using far more words than the point actually needs.","Alert and responsive to signals, picking them up early and adjusting."]', '["mold breaker","advocate for","lean on","sleuthing","hyperscaler"]', 'forced and not believable', '["hard to understand","too costly to be practical","carefully checked by experts"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_contrived_0_recognition', 's_contrived_0', 'recognition', NULL, NULL, 328, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
