INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_verifiability_verifiable_rewards', 'verifiability/verifiable rewards', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_verifiability_verifiable_rewards_0', 'e_verifiability_verifiable_rewards', 0, 'verifiability', '["verifiable"]', 'Whether a claim can be checked by someone other than whoever made it.', 'People hear it as trustworthy, but a number can be easy to check and still wrong. Promise it only if you can say who checks it and against what.', 'Our advantage isn''t that the model is right more often, it''s the verifiability — every number traces back to a filing.', '[{"text":"A compliance officer asks what makes AI output acceptable inside a regulated process, and your answer is that every figure traces back to a document anyone can open.","setting":"work"},{"text":"You are arguing for the design that shows its sources over the one that is more accurate but opaque.","setting":"work"},{"text":"A board member asks why you trust one vendor''s numbers more than another''s.","setting":"work"},{"text":"A friend forwards you a health claim, and you want a word for exactly what it lacks: no way for anyone outside to check it.","setting":"life"},{"text":"You are comparing two second-hand cars and one comes with a full documented service history.","setting":"life"}]', '["The property of work that runs for many steps before anyone can tell whether it worked.","A voluntary group of people who do the same work and meet to trade what they learn.","The words a business actually uses mapped onto the raw tables underneath them.","Weight and seriousness in how a person carries themselves.","To decide as you go, taking your lead from how things develop."]', '["gravitas","harness","advocate for","run it by you","blanket approval"]', 'how easily others can check it', '["feedback a computer can check","how widely it is used","how strongly customers recommend it"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
