INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_panopticon', 'panopticon', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_panopticon_0', 'e_panopticon', 0, 'panopticon', '["panoptic"]', 'A place where anyone could be watched at any time, so everyone acts as if they are.', 'It is a criticism about power over people, from Foucault. If you only mean careful monitoring, it sounds like an accusation.', 'If every prompt is logged and reviewed, we''ve built a panopticon and people will stop experimenting.', '[{"text":"You are arguing against logging every internal AI interaction, and your point is that people behave differently when they might be watched.","setting":"work"},{"text":"A colleague proposes recording all agent sessions for quality review. You want a word for what that does to how people use the tool.","setting":"work"},{"text":"You are describing a neighbourhood where every corner has a camera, and how differently people carry themselves there.","setting":"life"},{"text":"Talking about social media with a friend, you want the word for a place whose power comes from the possibility of being watched rather than the fact of it.","setting":"life"}]', '["A funded, staffed team that concentrates a scarce capability and sets how it is used.","A voluntary group of people doing the same work who meet to trade what they are learning.","A rig that exercises a system to see how it behaves.","To put right something that was wrong.","Proceeding by small additions, each standing on its own."]', '["blanket approval","watch outs","inroads","executive presence","run it by you"]', 'a place where all are watched', '["a room with no windows","a building open to the public","a large public square"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_panopticon_0_recognition', 's_panopticon_0', 'recognition', NULL, NULL, 356, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_panopticon_0_identify', 's_panopticon_0', 'identify', NULL, NULL, 357, '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
