INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_disparage', 'disparage', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_disparage_0', 'e_disparage', 0, 'disparage', '["disparaging","disparagement"]', 'To speak of someone or something in a way that quietly lowers how others see it.', 'Saying you do not want to disparage someone tells people you are about to. Calling honest criticism disparagement is a way to dodge it, and people notice.', 'I''m not trying to disparage the previous team — they were solving a different problem with a fifth of the budget.', '[{"text":"You want to criticise a decision without it sounding like you are running down the people who made it.","setting":"work"},{"text":"A friend keeps making small remarks that quietly diminish his partner''s job, and you are describing the pattern to someone else.","setting":"life"},{"text":"A relative constantly talks down the town you moved to, and you want a precise word for what he is doing rather than just calling him rude.","setting":"life"},{"text":"You are reading a review that never quite attacks the book but leaves it smaller than it found it.","setting":"life"},{"text":"Someone asks why you left a group chat, and the honest answer is the constant belittling of one member.","setting":"life"}]', '["To make something already said finally make sense by laying the reasoning out in order.","To back a claim with evidence that somebody else is able to check for themselves.","To turn an object in memory into bytes that can be stored or sent.","To avoid something deliberately and on principle.","To rely on someone to carry part of the weight."]', '["play it by ear","daily driver","vertical","north star","finesse"]', 'to speak badly of', '["to praise in public","to cut costs","to ask for advice"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
