INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_diaspora', 'diaspora', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_diaspora_0', 'e_diaspora', 0, 'diaspora', '["diasporic"]', 'A people scattered far from a homeland they still keep ties to.', 'Using it loosely, for ex-colleagues or team alumni, sounds careless to people whose families are part of one. For former staff, say alumni network.', 'The growth story there is remittances — money moving back through the diaspora — not domestic demand.', '[{"text":"A friend describes a wedding where everyone''s parents left the same country decades ago and almost nobody has been back.","setting":"life"},{"text":"You are explaining why one neighbourhood has three bakeries selling the same bread from one small region.","setting":"life"},{"text":"You are reading about a language kept alive abroad long after it faded where it began.","setting":"life"},{"text":"You are explaining to a colleague that a country''s economy runs largely on money sent home by people living overseas.","setting":"work"}]', '["The property of work that runs for many steps before anyone can tell if it worked.","A funded, staffed team that concentrates a scarce capability in one place.","A rule of thumb that gets a good enough answer quickly.","Using far more words than the point needs.","To make a bad situation worse."]', '["cognizant","first principles","second order effects","esoteric","broad"]', 'a people spread far from home', '["a large religious gathering","a festival held in many cities","a council of tribal elders"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
