INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_sleuthing_out', 'sleuthing (out)', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_sleuthing_out_0', 'e_sleuthing_out', 0, 'sleuthing', '["sleuth","sleuth out","sleuthing out","sleuthed out"]', 'Careful searching to find facts that nobody has written down.', 'It is light and a little playful. About a colleague it praises effort, but about your own work to a sponsor it can make real analysis sound unimportant.', 'Nobody could tell me which system owned that field, so I spent Tuesday sleuthing it out of the commit history.', '[{"text":"You spent a day working out which team owns an undocumented field by reading commit history and four-year-old tickets.","setting":"work"},{"text":"You want to credit a colleague who found the cause of a recurring cost spike that nobody had been able to explain.","setting":"work"},{"text":"A director asks how you established that two suppliers on the list are actually the same company.","setting":"work"},{"text":"You finally worked out which neighbour has been leaving flowers in the stairwell.","setting":"life"},{"text":"From photographs and a few names, you pieced together where your grandmother lived before the family moved.","setting":"life"}]', '["A funded, staffed team that concentrates a scarce capability in one place.","Permission given once and in advance to cover a whole class of decisions.","To avoid something deliberately and on principle.","The most senior people in a firm, spoken of as one.","Weight and seriousness in how a person carries themselves."]', '["advocate","run it by you","incremental","fan-out","progressive"]', 'careful searching for facts', '["guessing without any evidence","writing up a final report","asking a manager for help"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
