INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_ephemeral', 'ephemeral', NULL, '[]', 'ready', '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_ephemeral_0', 'e_ephemeral', 0, 'ephemeral', '["ephemerality"]', 'Lasting only a short time, and built that way on purpose.', 'In technical talk it is a claim, and people will ask about the logs and cached data. Elsewhere it sounds literary and a bit showy when spoken.', 'Every agent run gets an ephemeral workspace — it exists for the task and nothing survives it.', '[{"text":"You are describing a design where each run gets a fresh environment that is destroyed the moment it finishes.","setting":"work"},{"text":"A security reviewer asks how long the credentials the agent uses stay valid, and the answer is nine minutes.","setting":"work"},{"text":"You are justifying why you do not want a permanent copy of the intermediate data kept anywhere.","setting":"work"},{"text":"You are telling a friend that the best thing about that festival is how the whole town it builds is gone by Monday.","setting":"life"},{"text":"You want a word for how quickly a mood of collective optimism came and went.","setting":"life"}]', '["Safe to run more than once, because a second run changes nothing the first did not.","A basic building block a platform hands you and expects you to compose with.","Covering a wide range rather than a narrow one.","To put right something that was wrong.","The most senior people, taken as one group."]', '["rectify","first order effects","center of excellence","failure mode","serialize"]', 'lasting a short time', '["built to last","hidden from most users","easy to repair"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
