INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, gloss, gloss_distractors, prompt_version, created_at, updated_at) VALUES ('s_superset_0', 'e_superset', 0, 'superset', '["strict superset"]', 'A set that holds everything another set holds, and more besides.', 'It is a precise claim, so if any of the old one is missing, say covers most of instead. Used loosely about people''s skills, it reads as a ranking of people.', 'The new API is a strict superset of the old one, so nothing anybody has built stops working.', '[{"text":"You are reassuring a team that the replacement platform does everything the old one did and more, so nothing they rely on disappears.","setting":"work"},{"text":"A sponsor asks whether consolidating three tools into one will cost anybody a capability they currently have.","setting":"work"},{"text":"In an architecture review you want the exact word for a new interface that contains every method of the previous one.","setting":"work"},{"text":"You are pushing back on a migration plan because the target covers only most of what the current system does, not all of it.","setting":"work"}]', '["A slice of the market defined by the industry it serves, such as banking or health.","An isolated environment where something runs without touching anything real.","A rule of thumb that gets you a good enough answer quickly.","To make a bad situation worse.","Alert and responsive to signals, adjusting early."]', '["frontier","obfuscate","esoteric","vertical","rectify"]', 'a larger group that includes another', '["a smaller part of a group","the overlap between two separate groups","two groups with nothing shared"]', 4, '2026-09-26T05:00:00.000Z', '2026-09-26T05:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, gloss=excluded.gloss, gloss_distractors=excluded.gloss_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
